import Flutterimport UIKitimport Braintreeclass SceneDelegate: FlutterSceneDelegate {    override func scene(        _ scene: UIScene,        openURLContexts URLContexts: Set<UIOpenURLContext>    ) {        for context in URLContexts {            if BTAppContextSwitcher.sharedInstance.handleOpen(context.url) {                return            }        }    }    override func scene(        _ scene: UIScene,        continue userActivity: NSUserActivity    ) {        guard userActivity.activityType == NSUserActivityTypeBrowsingWeb,              let url = userActivity.webpageURL else {            return        }        BTAppContextSwitcher.sharedInstance.handleOpen(url)    }}